-- =====================================================================
-- MES 安全环保检测（SET）模块 菜单+按钮 SQL（P0 6 + P1 12 = 18 功能）
-- 依据运行库 md 惯例：MES 顶部 5100(/mes) > 目录 type1 > 功能菜单 type2 > 按钮 type3
-- 预留 ID 段 34000~34200（避让官方 5xxx/HRM 30xxx/FMS 32xxx）；如冲突请改段
-- 说明：超级管理员(super_admin)自动拥有全部菜单，无需绑定 system_role_menu；
--       租户普通角色如需授权，另跑 system_role_menu 绑定（本文件不含）。
-- 注意：component 为『前端页面契约』，须与 txgy-ui-admin-vben 页面文件一致后
--       方可应用；应用后请清 Redis 菜单/权限缓存并重新登录。
-- 列：id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,create_time,updater,update_time,deleted
-- =====================================================================

-- 防重清理（若需重跑本文件）
DELETE FROM system_menu WHERE id BETWEEN 34000 AND 34200;
DELETE FROM system_role_menu WHERE menu_id BETWEEN 34000 AND 34200;



















